import { useState } from 'react'

const round = (n) => String(Math.round(n * 10) / 10)

export function Converter() {
  const [s, setS] = useState({ scale: 'c', value: '' })
  const num = parseFloat(s.value)
  const valid = s.value !== '' && !Number.isNaN(num)
  const c = s.scale === 'c' ? s.value : valid ? round(((num - 32) * 5) / 9) : ''
  const f = s.scale === 'f' ? s.value : valid ? round((num * 9) / 5 + 32) : ''
  return (
    <div>
      <label>Celsius <input value={c} onChange={(e) => setS({ scale: 'c', value: e.target.value })} /></label>
      <label>Fahrenheit <input value={f} onChange={(e) => setS({ scale: 'f', value: e.target.value })} /></label>
    </div>
  )
}

