export function createQueryCache({ now = Date.now } = {}) {
  const map = new Map()
  return {
    fetchQuery(key, fn, staleTime = 0) {
      const e = map.get(key)
      if (e?.promise) return e.promise
      if (e && 'data' in e && now() - e.updatedAt < staleTime) return Promise.resolve(e.data)
      const entry = e ?? {}
      entry.promise = Promise.resolve().then(fn).then(
        (data) => { entry.data = data; entry.updatedAt = now(); entry.promise = null; return data },
        (err) => { entry.promise = null; throw err },
      )
      map.set(key, entry)
      return entry.promise
    },
    invalidate(key) { const e = map.get(key); if (e) e.updatedAt = -Infinity },
  }
}

