import { expect, test } from 'vitest'
import { createQueryCache } from './queryCache'

test('dedupes in-flight requests', async () => {
  let calls = 0
  const cache = createQueryCache()
  const fn = async () => { calls++; return 'ada' }
  const [a, b] = await Promise.all([cache.fetchQuery('u', fn, 1000), cache.fetchQuery('u', fn, 1000)])
  expect([a, b, calls]).toEqual(['ada', 'ada', 1])
})

test('reuses fresh data, refetches stale data', async () => {
  let t = 0, calls = 0
  const cache = createQueryCache({ now: () => t })
  const fn = async () => ++calls
  await cache.fetchQuery('k', fn, 100)
  t = 50
  expect(await cache.fetchQuery('k', fn, 100)).toBe(1)
  t = 200
  expect(await cache.fetchQuery('k', fn, 100)).toBe(2)
})

test('invalidate forces a refetch, errors are not cached', async () => {
  let calls = 0
  const cache = createQueryCache()
  await cache.fetchQuery('k', async () => ++calls, 1e9)
  cache.invalidate('k')
  expect(await cache.fetchQuery('k', async () => ++calls, 1e9)).toBe(2)
  await expect(cache.fetchQuery('bad', async () => { throw new Error('x') })).rejects.toThrow('x')
  expect(await cache.fetchQuery('bad', async () => 'ok')).toBe('ok')
})

