export function createSlice({ name, initialState, reducers }) {
  const cases = new Map()
  const actions = {}
  for (const [key, fn] of Object.entries(reducers)) {
    const type = `${name}/${key}`
    cases.set(type, fn)
    const creator = (payload) => ({ type, payload })
    creator.type = type
    actions[key] = creator
  }
  const reducer = (state = initialState, action) => {
    const fn = cases.get(action.type)
    return fn ? fn(state, action) : state
  }
  return { name, reducer, actions }
}

