import { useSyncExternalStore } from 'react'

export function atom(initial) {
  let v = initial
  const subs = new Set()
  return {
    get: () => v,
    set: (n) => { v = typeof n === 'function' ? n(v) : n; subs.forEach((l) => l()) },
    subscribe: (l) => { subs.add(l); return () => subs.delete(l) },
  }
}

export function computed(fn, deps) {
  let v = fn()
  const subs = new Set()
  for (const d of deps) d.subscribe(() => { v = fn(); subs.forEach((l) => l()) })
  return { get: () => v, subscribe: (l) => { subs.add(l); return () => subs.delete(l) } }
}

export function useAtom(a) {
  const value = useSyncExternalStore(a.subscribe, a.get)
  return [value, a.set]
}

